#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"#include "..\SocketClient.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public SPROLOZ  {  int nValue;  int nType;  } Queue_ZadvSH;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintZadvSH(DefinePaint)  {  QueueP(Queue_ZadvSH);  //  double dValue = 0;  CShZadv* sh=NULL;  if (p->nNumber!=-1)	sh = (CShZadv*)PipeSh;  else  if (p->nSocketNumber!=-1)	sh=(CShZadv*)q.m_pSocket->Sh(p->nSocketNumber);  //  if (sh==NULL)	  return 1;  switch ( p->nValue )    {    case 0:dValue = sh->Vent   ;break;    default: dValue = sh->VentZ;break;    }  //  if ( p->nType == 0 ) DrawValue( hDC, p, dValue, "%" );  else  if ( p->nType == 1 )    {    ASSERT(0);    // Удалено из модели    //COLORREF color = (fabs(sh.m_dVentD)>1) ? 0xff : 0xff0000;    ////    //double X = (dValue+100.)/(200.);    //int x = int(p->mRect.left*(1.-X) + X*p->mRect.right);    //x = max(x,p->mRect.left );    //x = min(x,p->mRect.right-1);    //CMyPen pen( hDC, color, 3 );    //::MoveToEx( hDC, x, p->mRect.top, NULL );    //::LineTo  ( hDC, x, p->mRect.bottom );    }  else  if ( p->nType == 2 )    {    if ( ::IsMnemoStyle(MNEMO_EDIT) )    if ( !IsTypeOk )      {      TransparentRect( hDC, p->mRect, 0x80ff, 0xffffff );      }    }  else  if ( p->nType == 3 )    {    const char* text = NULL;    if ( sh->Eq_State( CZadv::DRY_STEAM ) )      {      static char* txt = "Идет сухой пар";      text = txt;      }    else    if ( sh->Eq_State( CZadv::CONDENSAT ) )      {      static char* txt = "Идет конденсат";      text = txt;      }    //    if ( text != NULL )      {      ::DrawText( hDC, text, lstrlen(text), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );      }    //    }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddZadvSH(DefineTegs)  {  //  AddQueueEx(Queue_ZadvSH);  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintZadvSH;  p->nSocketNumber=-1;  p->nNumber=-1;  //  STegObj obj[] =    {    { 'I', "type" , &p->nType },    // Дополнительная информация    EXT_QUEUE    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  AddPRSH( def, id_Zadv, teg[0].value, p, p->nValue );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~